"use strict";(self.rspackChunkboser_frontend=self.rspackChunkboser_frontend||[]).push([[741],{35084(t){t.exports=JSON.parse('{"mining-stats.tuner.stage.stabilizing_temperature":"Стабилизация температуры","mining-stats.tuner.stage.optimizing_efficiency":"Оптимизация эффективности","mining-stats.tuner.stage.testing_performance_profile":"Проверка профиля производительности","mining-stats.tuner.stage.tuning_individual_chips":"Настройка отдельных чипов","mining-stats.tuner.stage.continuous_tuning":"Непрерывный тюнинг","mining-stats.tuner.stage.stable":"Стабильно","mining-stats.tuner.stage.not_running":"Тюнер не запущен","mining-stats.tuner.stage.running_with_fixed_settings":"Работа с фиксированными настройками","mining-stats.dps.disabled":"Отключено","mining-stats.dps.initial_power_target":"Включено","mining-stats.dps.initial_hashrate_target":"Включено","mining-stats.dps.lowered_power_target":"Целевая мощность изменена на {powerTargetW, number, ::.00} Вт","mining-stats.dps.lowered_hashrate_target":"Целевой хешрейт изменён на {hashrate}/s","mining-stats.dps.mining_shutdown":"Майнинг остановлен, возобновится через {countdown}","advanced-settings.allow_disabling_hashboards_on_nopic_miners.title":"Отключение хеш-плат на майнерах без PIC","advanced-settings.allow_disabling_hashboards_on_nopic_miners.description":"Позволяет майнерам без PIC продолжать майнинг с повреждённой хеш-платой в обход штатного защитного отключения. Используйте, только если понимаете риски.","advanced-settings.allow_missing_voltage_feedback.title":"Разрешить работу без обратной связи по напряжению","advanced-settings.allow_missing_voltage_feedback.description":"Позволяет запускать майнер без обратной связи по напряжению от PIC или блока питания. Отключает проверку напряжения и обнаружение короткого замыкания. Используйте, только если понимаете риски.","advanced-settings.cgminer_readonly.title":"CGMiner API только для чтения","advanced-settings.cgminer_readonly.description":"Если включено, все изменяющие команды CGMiner API блокируются. Это касается управления пулами (добавление/удаление/замена/включение/отключение/переключение) и управления майнингом (пауза/возобновление).","advanced-settings.defrost_temperature_limit_c.title":"Температурный предел разморозки","advanced-settings.defrost_temperature_limit_c.description":"При достижении температуры разморозки майнер прекращает прогрев хеш-плат и продолжает запуск. Рекомендуемое значение для иммерсионных и Hydro-майнеров — 10 °C; для майнеров с воздушным охлаждением задайте температуру под свои условия. Учтите, что запуск слишком холодных машин может навредить оборудованию.","advanced-settings.defrost_timeout_mode.title":"Режим таймаута разморозки","advanced-settings.defrost_timeout_mode.description":"Определяет, как долго работает прогрев хеш-плат. «Без ограничения» — разморозка идёт, пока хеш-плата не прогреется. «По таймеру» — разморозка останавливается по истечении «Длительность таймаута разморозки».","advanced-settings.defrost_timeout_mode.option.indefinite":"Без ограничения","advanced-settings.defrost_timeout_mode.option.timed":"По таймеру","advanced-settings.defrost_timeout_s.title":"Длительность таймаута разморозки","advanced-settings.defrost_timeout_s.description":"Таймаут прогрева хеш-плат в секундах.","advanced-settings.enable_continuous_tuning.title":"Непрерывный тюнинг","advanced-settings.enable_continuous_tuning.description":"Продолжает непрерывно настраивать майнер после завершения первоначального тюнинга.","advanced-settings.enable_defrost.title":"Разморозка хеш-плат","advanced-settings.enable_defrost.description":"Прогревает холодные хеш-платы, чтобы майнинг мог запуститься при низкой температуре.","advanced-settings.ignore_internal_chip_temperature.title":"Отключить защиту по температуре чипов","advanced-settings.ignore_internal_chip_temperature.description":"Отключает автоматическую паузу при достижении внутренним чипом ОПАСНОЙ температуры. Может привести к перегреву или повреждению оборудования.","advanced-settings.mdns_enabled.title":"Анонсировать через mDNS","advanced-settings.mdns_enabled.description":"Если включено, майнер анонсирует свой веб-интерфейс и API через mDNS/DNS-SD, чтобы его можно было найти в локальной сети без знания IP-адреса. На крупных майнерах по умолчанию отключено, так как в плоских сетях ферм link-local multicast рассылается на каждый порт. На небольших майнерах по умолчанию включено; значение по умолчанию для платформы сообщает схема устройства.","advanced-settings.min_fan_pwm.title":"Минимальный PWM вентиляторов","advanced-settings.min_fan_pwm.description":"Минимальный PWM вентиляторов в процентах, используемый, когда в «Режим минимального PWM вентиляторов» выбран «Ручной».","advanced-settings.min_fan_pwm_mode.title":"Режим минимального PWM вентиляторов","advanced-settings.min_fan_pwm_mode.description":"Определяет, как задаётся минимальный PWM вентиляторов при запуске. В режиме «Авто» майнер выполняет автонастройку вентиляторов, чтобы найти минимальные обороты. В режиме «Ручной» используется фиксированное значение из «Минимальный PWM вентиляторов».","advanced-settings.min_fan_pwm_mode.option.auto":"Авто","advanced-settings.min_fan_pwm_mode.option.manual":"Ручной","advanced-settings.normal_ramping_time_down_mode.title":"Режим обычного времени снижения мощности","advanced-settings.normal_ramping_time_down_mode.description":"Определяет время снижения мощности при выключении или перезапуске. По умолчанию используется встроенное время. В режиме «Пользовательский» применяется значение «Обычное время снижения мощности».","advanced-settings.normal_ramping_time_down_mode.option.unchanged":"Встроенный","advanced-settings.normal_ramping_time_down_mode.option.custom":"Пользовательский","advanced-settings.normal_ramping_time_down_s.title":"Обычное время снижения мощности","advanced-settings.normal_ramping_time_down_s.description":"Определяет, как быстро майнер снижает частоту. Меньшие значения могут увеличить нагрузку на компоненты и сократить срок службы устройства. Большие значения могут ограничиваться при выключении и перезапуске майнера.","advanced-settings.normal_ramping_time_up_mode.title":"Режим обычного времени выхода на мощность","advanced-settings.normal_ramping_time_up_mode.description":"Определяет время выхода на мощность после загрузки или перезапуска (не после паузы/возобновления). По умолчанию используется встроенное время. В режиме «Пользовательский» применяется значение «Обычное время выхода на мощность».","advanced-settings.normal_ramping_time_up_mode.option.unchanged":"Встроенный","advanced-settings.normal_ramping_time_up_mode.option.custom":"Пользовательский","advanced-settings.normal_ramping_time_up_s.title":"Обычное время выхода на мощность","advanced-settings.normal_ramping_time_up_s.description":"Определяет, как быстро майнер выходит на мощность после загрузки или перезапуска (не после паузы/возобновления). Меньшие значения могут увеличить нагрузку на компоненты и сократить срок службы устройства.","advanced-settings.overheat_recovery_mode.title":"Автовосстановление после перегрева","advanced-settings.overheat_recovery_mode.description":"Переопределяет поведение после паузы майнера из-за ОПАСНОЙ температуры. По умолчанию автоматическое возобновление после остывания включено для майнеров с воздушным и иммерсионным охлаждением и отключено для Hydro-майнеров (для защиты от повреждений, когда охлаждающая вода не циркулирует).","advanced-settings.overheat_recovery_mode.option.unchanged":"Встроенный","advanced-settings.overheat_recovery_mode.option.disabled":"Отключён","advanced-settings.overheat_recovery_mode.option.enabled":"Включён","advanced-settings.rambo_mode.title":"Режим Rambo","advanced-settings.rambo_mode.description":"Режим Rambo — это «уровень отказоустойчивости». Игнорирует некоторые ошибки связи с чипами и блоком питания.","advanced-settings.rambo_mode.option.disabled":"Отключён","advanced-settings.rambo_mode.option.cautious":"Осторожный","advanced-settings.rambo_mode.option.maximum":"Максимальный","advanced-settings.start_cooldown_mode.title":"Режим охлаждения перед запуском","advanced-settings.start_cooldown_mode.description":"Управляет охлаждением перед запуском или возобновлением майнинга. По умолчанию майнер ждёт, пока чипы остынут до заданной температуры. Режим «По таймеру» ограничивает общее время ожидания. Режим «Отключён» полностью пропускает охлаждение. Запуск со слишком горячими чипами может навредить оборудованию.","advanced-settings.start_cooldown_mode.option.unchanged":"Встроенный","advanced-settings.start_cooldown_mode.option.timed":"По таймеру","advanced-settings.start_cooldown_mode.option.disabled":"Отключён","advanced-settings.start_cooldown_timeout_s.title":"Таймаут охлаждения перед запуском","advanced-settings.start_cooldown_timeout_s.description":"Максимальное время, которое майнер тратит на охлаждение чипов перед запуском или возобновлением майнинга.","advanced-settings.startup_delay_max_s.title":"Максимальная задержка запуска","advanced-settings.startup_delay_max_s.description":"Максимальная случайная задержка перед запуском майнинга. При каждом запуске или возобновлении после паузы выбирается случайное значение от 0 до этого максимума. Помогает запускать майнеры на ферме поэтапно после сбоя питания."}')}}]);